const crypto = require('crypto');

function b64uDecode(s) {
  s = s.replace(/-/g, '+').replace(/_/g, '/');
  while (s.length % 4) s += '=';
  return Buffer.from(s, 'base64').toString('utf8');
}

const item = $input.first().json;
const authHeader = item.headers?.authorization ?? '';
const token = authHeader.replace(/^Bearer\s+/i, '');
if (!token) throw new Error('401: Token eksik');

const parts = token.split('.');
if (parts.length !== 3) throw new Error('401: Geçersiz token');

const [header, payload, sig] = parts;
const expected = crypto
  .createHmac('sha256', $env.JWT_SECRET)
  .update(`${header}.${payload}`)
  .digest('base64')
  .replace(/\+/g, '-').replace(/\//g, '_').replace(/=/g, '');

if (sig !== expected) throw new Error('401: Geçersiz imza');

const claims = JSON.parse(b64uDecode(payload));
if (claims.exp < Math.floor(Date.now() / 1000)) throw new Error('401: Token süresi dolmuş');

const body = item.body ?? {};
if (!body.news_id) throw new Error('400: news_id zorunlu');
if (!body.client_id) throw new Error('400: client_id zorunlu');

return [{ json: { news_id: body.news_id, client_id: body.client_id, _sub: claims.sub } }];

const { news_id, client_id, _sub } = $input.first().json;
const job_id = require('crypto').randomUUID();
return [{ json: { job_id, news_id, client_id, _sub } }];

