// Bir önceki adımdan job_id'yi koru (Postgres node yeni item döndürür)
const prev = $('Job ID Üret').first().json;
return [{ json: prev }];

// Haber ve persona verilerini + context'i birleştir
const ctx = $('Context Taşı 1').first().json;
const news = $('Haber Çek').first().json;
const persona = $('Persona Çek').first().json;

if (!news?.title) throw new Error('Haber bulunamadı: ' + ctx.news_id);
if (!persona?.identity) throw new Error('Persona bulunamadı: ' + ctx.client_id);

return [{ json: { ...ctx, news, persona } }];

// Gemini prompt'u oluştur — gemini-prompt-engineering skill'inden
const d = $('Veri Birleştir').first().json;
const persona = d.persona;
const news = d.news;

const IDEOLOGY_BLOCKS = {
  conservative: `Muhafazakar, milliyetçi, manevi değerlere bağlı bir perspektif.
Vatan, millet, aile, ecdat, şehit, gazi, bayrak vurguları doğal.
"Aziz milletim", "değerli kardeşlerim", "milletimizin sağduyusu" gibi hitaplar uygun.
Kelimeler: birlik, beraberlik, kardeşlik, dayanışma, fedakarlık, ecdat, mukaddes, kutlu.
KULLANMA: küresel, evrensel, bireysel, seküler, kozmopolit gibi nesnel-mesafeli sözcükler.`,
  social_democrat: `Sosyal demokrat, laik, eşitlikçi bir perspektif.
Emek, eşitlik, sosyal adalet, demokrasi, laiklik, hukuk devleti vurguları.
"Değerli yurttaşlarımız", "emekçi kardeşlerim", "halkımız" gibi hitaplar uygun.
Kelimeler: hak, özgürlük, eşitlik, dayanışma, emek, kadın, çocuk, çevre, bilim, akıl.
KULLANMA: kısmet, nasip, ecdat gibi muhafazakar sözcükler.`,
  liberal: `Liberal, bireyci, özgürlükçü bir perspektif.
Birey, özgürlük, piyasa, girişimcilik, akıl, bilim, hukuk devleti vurguları.
"Değerli vatandaşlarımız", "bireyler" gibi hitaplar uygun.
Kelimeler: özgürlük, bireysel hak, piyasa, rekabet, girişimcilik, inovasyon, akıl.
KULLANMA: cemaat, ümmet, toplumcu sözcükler.`,
  nationalist: `Milliyetçi, vatansever, Türklük vurgulu bir perspektif.
Vatan, millet, Türklük, şehit, gazi, tarih, ecdat odaklı.
"Aziz Türk milletim", "soylu milletimiz" gibi hitaplar uygun.
Kelimeler: vatan, millet, Türk, bayrak, şehadet, gazilik, kahramanlık, beka.
KULLANMA: küresel vatandaşlık, evrenselcilik gibi sözcükler.`,
  left: `Sol, halkçı, emek odaklı bir perspektif.
Emek, sınıf, halk, mücadele, dayanışma vurguları.
"Halkımız", "emekçi kardeşlerim", "ezilenler" gibi hitaplar uygun.
Kelimeler: emek, sınıf, mücadele, dayanışma, eşitlik, halkçı.
KULLANMA: piyasa, rekabet, girişimci gibi liberal sözcükler.`,
};

const ideologyBlock = IDEOLOGY_BLOCKS[persona.ideology] || IDEOLOGY_BLOCKS.conservative;

const voiceExamples = Array.isArray(persona.voice_examples)
  ? persona.voice_examples.map((ex, i) => {
      const text = ex.example || ex.text || ex;
      return `Örnek ${i + 1} (${ex.tone || 'genel'}): "${text}"`;
    }).join('\n')
  : '';

const themesText = (persona.themes || []).join(', ');
const bannedTopicsText = (persona.banned_topics || []).join(', ') || 'yok';
const bannedWordsText = (persona.banned_words || []).join(', ') || 'yok';
const maxChars = persona.max_chars || 280;
const addressForm = persona.address_form || '';

const pubDate = news.published_at
  ? new Date(news.published_at).toLocaleDateString('tr-TR')
  : 'Belirtilmemiş';

const prompt = `ROL: Sen ${persona.identity} için sosyal medya yazıyorsun. Profesyonel sosyal medya yöneticisisin.

İDEOLOJİK ÇERÇEVE:
${ideologyBlock}

ÜSLUP REFERANSI (bu örneklerin tonunu birebir yakala):
${voiceExamples}

TEMATİK ODAK:
- Bu temalara değin: ${themesText}
- Bu konulara KESİNLİKLE değinme: ${bannedTopicsText}
- Bu kelimeleri KESİNLİKLE kullanma: ${bannedWordsText}
- Hitap şekli: "${addressForm}"

HABER:
Başlık: ${news.title}
Özet: ${news.description || '(özet yok, sadece başlık bağlamıyla yaz)'}
Kaynak: ${news.source_name}
Tarih: ${pubDate}

GÖREV: Bu haberi ${persona.identity} bakış açısıyla yorumlayan 3 farklı tweet üret.
Her tweet, devlet adamı olgunluğunda, kişisel bir tepki/yorum niteliğinde olmalı.
Haber başlığını tekrar etme — haberin özünü kavrayıp, ${persona.identity}'in bu konudaki düşüncesini/duygusunu yansıtan bir tweet yaz.

VARYANTLAR:
1. "sert" — Net, kararlı, mesajın arkasında durulan ton
2. "uzlasmaci" — Birleştirici, milleti kucaklayan, sakin ton
3. "espriyle" — Hafif esprili, samimi, doğal dilde ton

KISITLAR (mutlaka):
- Her tweet maksimum ${maxChars} karakter
- Türkçe DIŞINDA hiçbir kelime KULLANMA
- Emoji ASLA kullanma
- Hashtag ASLA kullanma
- URL ekleme
- "İşte detaylar", "okumak için tıkla" gibi gazete dilini KULLANMA
- Yasaklı kelime listesindeki kelimeleri hiçbir varyantta kullanma

ÇIKTI FORMATI (SADECE bu JSON, başka hiçbir metin yazma):
{"variants":[{"label":"sert","content":"...","char_count":0},{"label":"uzlasmaci","content":"...","char_count":0},{"label":"espriyle","content":"...","char_count":0}]}

DÜŞÜN: Haberin özünü kavra. ${persona.identity}'in bu konuda ne hissedeceğini hayal et. O duyguyu yansıtan kısa ve nitelikli bir tweet yaz. Üslup örneklerine sadık kal.`;

return [{ json: { ...d, prompt } }];

// Gemini yanıtını parse et ve doğrula
const ctx = $('Context Taşı 2').first().json;
const geminiResponse = $input.first().json;

function cleanJsonResponse(text) {
  if (typeof text !== 'string') text = JSON.stringify(text);
  text = text.replace(/^```json\s*/i, '').replace(/^```\s*/, '').replace(/```\s*$/g, '');
  text = text.trim();
  const firstBrace = text.indexOf('{');
  const lastBrace = text.lastIndexOf('}');
  if (firstBrace !== -1 && lastBrace !== -1) {
    text = text.slice(firstBrace, lastBrace + 1);
  }
  return text;
}

// Gemini yanıt yapısı: candidates[0].content.parts[0].text
const rawText = geminiResponse?.candidates?.[0]?.content?.parts?.[0]?.text;
if (!rawText) throw new Error('Gemini boş yanıt döndürdü');

let parsed;
try {
  parsed = JSON.parse(cleanJsonResponse(rawText));
} catch {
  throw new Error('Gemini geçersiz JSON döndürdü: ' + rawText.substring(0, 200));
}

if (!parsed.variants || !Array.isArray(parsed.variants) || parsed.variants.length !== 3) {
  throw new Error('Beklenen 3 varyant gelmedi');
}

const validLabels = ['sert', 'uzlasmaci', 'espriyle'];
const maxChars = ctx.persona?.max_chars || 280;

const variants = parsed.variants.map(v => {
  if (!validLabels.includes(v.label)) throw new Error('Geçersiz varyant label: ' + v.label);
  const content = String(v.content || '').trim();
  if (!content) throw new Error('Boş varyant: ' + v.label);
  if (content.length > maxChars + 20) throw new Error(`Varyant çok uzun (${content.length} kar): ${v.label}`);
  return { label: v.label, content, char_count: content.length };
});

return [{ json: { ...ctx, variants } }];

// İçerik moderasyonu — flag'ler dolar, otomatik reject yok (insan karar verir)
const d = $('JSON Parse & Validate').first().json;
const persona = d.persona;
const bannedWords = persona.banned_words || [];
const maxChars = persona.max_chars || 280;
const URL_REGEX = /https?:\/\/\S+|www\.\S+/gi;
const HASHTAG_REGEX = /#\w+/g;

const moderatedVariants = d.variants.map(v => {
  const flags = [];
  const content = v.content;

  for (const word of bannedWords) {
    if (word && content.toLowerCase().includes(word.toLowerCase())) {
      flags.push(`banned_word:${word}`);
    }
  }
  if (content.length > maxChars) flags.push(`over_limit:${content.length}`);
  if (URL_REGEX.test(content)) flags.push('contains_url');
  if (HASHTAG_REGEX.test(content)) flags.push('contains_hashtag');

  return { ...v, moderation_flags: flags };
});

return [{ json: { ...d, variants: moderatedVariants } }];

// 3 draft'ı Postgres INSERT için SQL'e dönüştür
const d = $input.first().json;
const esc = (s) => s == null ? 'NULL' : `'${String(s).replace(/'/g, "''")}'`;
const escArr = (arr) => arr && arr.length ? `ARRAY[${arr.map(esc).join(',')}]::text[]` : `'{}'::text[]`;

const sqls = d.variants.map(v =>
  `INSERT INTO drafts (client_id, news_id, job_id, content, variant_label, status, moderation_flags)
   VALUES (${esc(d.client_id)}, ${esc(d.news_id)}, ${esc(d.job_id)}, ${esc(v.content)}, ${esc(v.label)}, 'pending', ${escArr(v.moderation_flags)})
   RETURNING id, variant_label;`
);

return sqls.map(sql => ({ json: { sql, job_id: d.job_id, client_id: d.client_id } }));

// Hata durumunda job'ı failed olarak işaretle
const crypto = require('crypto');
const errMsg = $input.first()?.json?.message ?? 'Bilinmeyen hata';

// Tüm olası context node'larından job_id bul
let job_id = null;
const contextNodes = ['Context Taşı 2', 'Context Taşı 1', 'Context Koru', 'Job ID Üret'];
for (const nodeName of contextNodes) {
  try {
    const j = $(nodeName).first()?.json?.job_id;
    if (j) { job_id = j; break; }
  } catch { /* node henüz çalışmamış olabilir */ }
}

if (!job_id) return [{ json: { skipped: true, error: errMsg } }];

const esc = (s) => `'${String(s).replace(/'/g, "''")}'`;
return [{ json: { sql: `UPDATE draft_jobs SET status='failed', error_message=${esc(errMsg.substring(0, 500))}, updated_at=now() WHERE id='${job_id}';`, job_id } }];
